const assert=require("node:assert/strict");
const fs=require("node:fs");
const page=fs.readFileSync("src/app/page.tsx","utf8");
const start=page.indexOf("const comparableCart = useMemo(() => {");
const end=page.indexOf("\n  const chainResults = useMemo",start);
const chainEnd=page.indexOf("\n  const ",end+20);
const guard=page.slice(start,end);
const chain=page.slice(end,chainEnd>end?chainEnd:end+2700);
assert.match(guard,/!isComparableWeightOfferV797\(item\)/);
assert.match(chain,/const sList = comparableCart/);
assert.match(chain,/const kList = comparableCart/);
assert.match(chain,/const sTotal = sList\.reduce/);
assert.match(chain,/const kTotal = kList\.reduce/);
const normal={id:"milk",source:"normal",price:2.5,quantity:1};
const weight={id:"loose-fruit",source:"offer",price:0,quantity:1,product:{ziiplyWeightOffer:true,ziiplyPricePendingWeight:true,comparisonPrice:4.99,comparisonPriceUnit:"kg"}};
const isWeight=x=>x.source==="offer"&&x.product?.ziiplyWeightOffer&&x.product?.comparisonPriceUnit==="kg"&&Number(x.product?.comparisonPrice)>0;
const eligible=x=>isWeight(x)||x.source!=="offer";
const cart=[normal,weight],unitComparison=cart.filter(eligible),euroComparison=cart.filter(x=>eligible(x)&&!isWeight(x));
assert.deepEqual(unitComparison.map(x=>x.id),["milk","loose-fruit"]);
assert.deepEqual(euroComparison.map(x=>x.id),["milk"]);
const matches={milk:{price:2.5,quantity:1},"loose-fruit":{price:4.99,quantity:1}};
const total=euroComparison.map(x=>matches[x.id]).reduce((sum,m)=>sum+m.price*m.quantity,0);
assert.equal(total,2.5);
console.log("PASS mixed basket: weight quote retained for unit comparison but excluded from chain euro total");
console.log("PASS chainResults source uses filtered comparableCart for both S and K totals");
